import { test, expect } from "playwright/test";

// This journey uses generated bytes, restricted runtime SQL and real journal reports.
test("loads 3000 transactions and explicitly posts one source-linked journal", async ({
  page,
}) => {
  test.setTimeout(120000);
  await page.goto("/");
  await expect(
    page.getByRole("button", { name: "Load demo books", exact: true }),
  ).toBeEnabled();
  await page
    .getByRole("button", { name: "Load demo books", exact: true })
    .click();
  await expect(
    page.getByText("3000 of 3000 transactions imported · Ready for review", {
      exact: true,
    }),
  ).toBeVisible({ timeout: 60000 });
  await page.reload();
  await expect(
    page.getByRole("button", { name: "Demo books loaded", exact: true }),
  ).toBeDisabled();
  await page.getByLabel("Entity and book").selectOption({
    label: "Fictional Harbor Design LLC / Synthetic acquisition / USD",
  });
  await page.getByText("Tools", { exact: true }).click();
  await page.getByRole("button", { name: "Accounts", exact: true }).click();
  await expect(page.locator("tfoot td")).toHaveText(["0.00", "0.00"]);
  await page.getByText("Tools", { exact: true }).click();
  await page
    .getByRole("button", { name: "Review transactions", exact: true })
    .click();
  const source = page.getByRole("combobox", {
    name: "Source account",
    exact: true,
  });
  await expect(source.locator("option")).toHaveCount(2);
  await source.selectOption({ index: 1 });
  // UUID ordering is deliberately opaque; the selected row supplies only its direction, never expected arithmetic.
  await expect(
    page.getByRole("button", { name: /^Review Fictional / }).first(),
  ).toBeVisible();
  const row = page
    .getByRole("button", { name: /^Review Fictional / })
    .first()
    .locator("xpath=ancestor::tr");
  const isInflow = (await row.textContent())!.includes("inflow");
  await row.getByRole("button").click();
  const category = page.getByRole("combobox", {
    name: "Category account",
    exact: true,
  });
  await category.selectOption({
    label: isInflow
      ? "4000 · Fictional service income · revenue"
      : "5000 · Fictional operating expenses · expense",
  });
  await page
    .getByRole("button", { name: "Create reviewed draft", exact: true })
    .click();
  await expect(
    page.getByRole("table", { name: "Exact proposed journal lines" }),
  ).toBeVisible();
  await page
    .getByRole("button", { name: "Review posting command", exact: true })
    .click();
  await expect(
    page.getByRole("button", { name: "Post journal", exact: true }),
  ).toBeEnabled();
  await page.reload();
  await expect(
    page.getByRole("button", { name: "Post journal", exact: true }),
  ).toBeEnabled();
  // Lose an actual committed execution response; reload must discover the same journal.
  let dropped = false;
  await page.route("**/v1/commands/*/execute", async (route) => {
    if (dropped) {
      await route.continue();
      return;
    }
    const response = await route.fetch();
    expect(response.ok()).toBe(true);
    await route.abort("failed");
    dropped = true;
  });
  await page.getByRole("button", { name: "Post journal", exact: true }).click();
  await expect.poll(() => dropped).toBe(true);
  await page.reload();
  await expect(
    page.getByText("Posting confirmed", { exact: true }),
  ).toBeVisible();
  await page
    .getByRole("button", { name: "Acknowledge result", exact: true })
    .click();
  await page.getByLabel("Entity and book").selectOption({
    label: "Fictional Harbor Design LLC / Synthetic acquisition / USD",
  });
  await page.getByText("Tools", { exact: true }).click();
  await page.getByRole("button", { name: "Accounts", exact: true }).click();
  await expect(page.locator("tfoot td")).toHaveText(
    isInflow ? ["100.01", "100.01"] : ["25.02", "25.02"],
  );
  await page.getByText("Tools", { exact: true }).click();
  await page
    .getByRole("button", { name: "Review transactions", exact: true })
    .click();
  await page
    .getByRole("combobox", { name: "Source account", exact: true })
    .selectOption({ index: 1 });
  await page
    .getByRole("combobox", { name: "Review status", exact: true })
    .selectOption("posted");
  await expect(
    page.getByRole("button", { name: /^Review Fictional / }),
  ).toHaveCount(1);
  await page.getByRole("button", { name: /^Review Fictional / }).click();
  await expect(page.getByText(/^Posted journal:/)).toBeVisible();
  await page
    .getByRole("button", { name: "View posted journal", exact: true })
    .click();
  await expect(
    page.getByRole("table", { name: "Immutable posted journal lines" }),
  ).toBeVisible();
  await page.screenshot({
    path: "test-results/populated-demo-review.png",
    fullPage: true,
  });
  await expect(
    page.getByRole("button", { name: "Review posting command", exact: true }),
  ).toHaveCount(0);
});
